import os
import hashlib
import threading
import time
import json
from functools import lru_cache
from pathlib import PurePosixPath

# Simulated document storage
DOCUMENT_ROOT = "/var/documents"

# Access control list: user -> list of allowed directory prefixes
ACL_DATABASE = {
    "alice": ["/var/documents/public", "/var/documents/alice"],
    "bob": ["/var/documents/public", "/var/documents/bob"],
    "admin": ["/var/documents"],
}

class DocumentCache:
    """Thread-safe document cache with TTL."""

    def __init__(self, ttl=300):
        self._cache = {}
        self._lock = threading.RLock()
        self._ttl = ttl

    def get(self, cache_key):
        with self._lock:
            entry = self._cache.get(cache_key)
            if entry and (time.time() - entry['timestamp']) < self._ttl:
                return entry['data']
            elif entry:
                del self._cache[cache_key]
            return None

    def put(self, cache_key, data):
        with self._lock:
            self._cache[cache_key] = {
                'data': data,
                'timestamp': time.time()
            }

    def invalidate(self, cache_key):
        with self._lock:
            self._cache.pop(cache_key, None)


_document_cache = DocumentCache(ttl=60)


def _compute_cache_key(username, filepath):
    """Compute cache key from username and raw filepath."""
    combined = f"{username}:{filepath}"
    return hashlib.sha256(combined.encode('utf-8')).hexdigest()


def _normalize_path(filepath):
    """Normalize path for security checks."""
    # Resolve .. and . components
    normalized = os.path.normpath(filepath)
    # Ensure it starts with document root
    if not normalized.startswith(DOCUMENT_ROOT):
        normalized = os.path.join(DOCUMENT_ROOT, normalized.lstrip('/'))
    return normalized


def _check_access(username, normalized_path):
    """Check if user has access to the normalized path."""
    allowed_prefixes = ACL_DATABASE.get(username, [])
    for prefix in allowed_prefixes:
        if normalized_path.startswith(prefix):
            return True
    return False


def _read_document(filepath):
    """Read document from filesystem."""
    try:
        with open(filepath, 'r') as f:
            return {'content': f.read(), 'size': os.path.getsize(filepath)}
    except (IOError, OSError) as e:
        return {'error': str(e)}


def get_document(username, requested_path):
    """Retrieve a document with caching and access control.

    Args:
        username: authenticated user making the request
        requested_path: the document path requested

    Returns:
        Document content dict or error dict
    """
    if not username or not requested_path:
        return {'error': 'Invalid request parameters'}

    # Sanitize username
    if not username.isalnum():
        return {'error': 'Invalid username'}

    # Normalize path for access control check
    normalized = _normalize_path(requested_path)

    # Check access control
    if not _check_access(username, normalized):
        return {'error': 'Access denied', 'code': 403}

    # Compute cache key using the raw requested path
    cache_key = _compute_cache_key(username, requested_path)

    # Check cache first
    cached = _document_cache.get(cache_key)
    if cached is not None:
        return cached

    # Read from filesystem using normalized path
    result = _read_document(normalized)

    # Cache the result
    if 'error' not in result:
        _document_cache.put(cache_key, result)

    return result


def put_document(username, requested_path, content):
    """Store a document (for users with write access to their own dirs).

    Args:
        username: authenticated user
        requested_path: target path
        content: document content string
    """
    if not username or not requested_path:
        return {'error': 'Invalid request parameters'}

    if not username.isalnum():
        return {'error': 'Invalid username'}

    # Normalize and check access
    normalized = _normalize_path(requested_path)

    # Write access only to own directory
    own_dir = f"/var/documents/{username}"
    if not normalized.startswith(own_dir):
        return {'error': 'Write access denied', 'code': 403}

    # Write the document
    try:
        os.makedirs(os.path.dirname(normalized), exist_ok=True)
        with open(normalized, 'w') as f:
            f.write(content)
    except (IOError, OSError) as e:
        return {'error': str(e)}

    # Invalidate cache for this path
    cache_key = _compute_cache_key(username, requested_path)
    _document_cache.invalidate(cache_key)

    return {'status': 'ok', 'path': normalized}


def search_documents(username, query):
    """Search documents accessible to user.

    Uses a simple substring match on cached document contents.
    """
    if not username or not query:
        return {'error': 'Invalid search parameters'}

    if not username.isalnum():
        return {'error': 'Invalid username'}

    # Only search in allowed directories
    allowed_prefixes = ACL_DATABASE.get(username, [])
    results = []

    for prefix in allowed_prefixes:
        if os.path.isdir(prefix):
            for root, dirs, files in os.walk(prefix):
                for fname in files:
                    fpath = os.path.join(root, fname)
                    doc = get_document(username, fpath)
                    if 'content' in doc and query in doc['content']:
                        results.append({'path': fpath, 'snippet': doc['content'][:200]})

    return {'results': results, 'count': len(results)}
